solution:
export async function retry<T>(fn: () => Promise<T>, maxAttempts: number): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < maxAttempts; i++) {
    try { return await fn(); } catch (e) { lastError = e; }
  }
  throw lastError;
}
